try{(function(){"use strict";if(!window.MC||!MC.reg||MC.tests.scoff)return;var a=[["Nahi","No"],["Haan","Yes"]],e="#16a34a",b="#65a30d",x="#d97706",j="#ea580c",h="#dc2626",g=["Ye hamari apni checklist hai, validated test nahi. Iska koi official cut-off nahi, ye sirf batati hai ki kitni baatein aap par lagu hui.","This is our own checklist, not a validated test. It has no official cut-off; it only shows how many points apply to you."],T=function(m,M,f){return f?[m,M,f]:[m,M]},o=function(m,M,f){var K=0,J;for(J=M;J<=f;J++)K+=m[J]||0;return K},t=["Madad ke liye Tele-MANAS 14416 (24x7) par baat kar sakte hain.","For support you can call Tele-MANAS 14416 (24x7)."],C=["Agar chakkar ya behoshi, seene me dard, dil ki dhadkan ka bigadna, ya ulti me khoon ho to turant doctor ya emergency (112) se milein.","If you have fainting, chest pain, an irregular heartbeat or blood in vomit, see a doctor or emergency care (112) right away."];MC.reg({id:"scoff",name:["Eating problem (quick screen)","Eating problem (quick screen)"],sub:["Khaane ki dikkat ka chhota screen, 5 sawal","Quick screen for eating problems, 5 questions"],max:5,opts:a,intro:["Apne khaane aur sharir ke baare me sochkar Haan ya Nahi chunein. Ye diagnosis nahi, sirf shuruaati screen hai.","Think about your eating and body and choose Yes or No. This is a first-step screen, not a diagnosis."],items:[T("Kya aap khud ko ulti karwate hain kyunki pet bahut bhara hua lagta hai?","Do you make yourself sick because you feel uncomfortably full?"),T("Kya aapko darr hai ki aap ye control kho dete hain ki kitna khate hain?","Do you worry you have lost control over how much you eat?"),T("Kya pichhle 3 mahine me aapka vajan bahut tezi se ghata (lagbhag 6 kg ya zyada)?","Have you recently lost a lot of weight quickly (about 6 kg or more in 3 months)?"),T("Kya aap khud ko mota maante hain jabki doosre kehte hain ki aap patle hain?","Do you believe you are fat when others say you are too thin?"),T("Kya khaana aapki zindagi par haavi rehta hai?","Would you say food dominates your life?")],calc:function(m){var M=o(m,0,4),f=M>=2;return{s:M,b:f?[0,5,"At or above cut-off",j,2]:[0,5,"Below cut-off",e,0],lines:[["Cut-off: 2 ya zyada 'Haan' par khaane ki dikkat ki jaanch layak. Ye diagnosis nahi hai.","Cut-off: 2 or more Yes answers is worth a fuller assessment. This is not a diagnosis."]],adv:f?["Kuch baatein khaane ki dikkat ki taraf ishara karti hain. Ye diagnosis nahi hai aur isme sharm ki baat nahi. Doctor ya psychiatrist se milein; jaldi madad lena sabse faydemand hai. Poora khaane ka check bhi le sakte hain. "+C[0]+" "+t[0],"Some answers point towards an eating problem. This is not a diagnosis and there is nothing to be ashamed of. See a doctor or psychiatrist; early help works best. You can also take the fuller eating check. "+C[1]+" "+t[1]]:["Cut-off se neeche hai. Agar khaane ya sharir ko lekar chinta badhe to doctor se baat karein.","Below the cut-off. If worry about eating or your body grows, talk to a doctor."]}}});var s=[["Hamesha","Always"],["Aam taur par","Usually"],["Aksar","Often"],["Kabhi-kabhi","Sometimes"],["Shayad hi","Rarely"],["Kabhi nahi","Never"]];MC.reg({id:"eat26",name:["Eating attitudes and fears","Eating attitudes and fears"],sub:["Khaane aur vajan ke baare me soch, 26 sawal","Thoughts about eating and weight, 26 questions"],max:78,opts:s,intro:["Har baat ke liye chuniye ki wo aap par kitni lagu hoti hai. Sab sawal khaane aur vajan ke baare me hain. Ye ek screen hai, diagnosis nahi; sirf sawalon ka pehla hissa hai.","For each statement, choose how often it applies to you. All questions are about eating and weight. This is a screen, not a diagnosis, and covers the attitudes part of the full questionnaire."],items:`Mujhe motapa se bahut darr lagta hai|I am terrified of being overweight
Bhookh lagne par bhi main khaana avoid karta/karti hoon|I avoid eating when I am hungry
Mera dhyan zyada tar khaane me hi rehta hai|I am preoccupied with food
Mujhe aise daure pade hain jisme main khaana rok nahi paaya/payi|I have had episodes of eating where I felt I could not stop
Main apna khaana chhote tukdon me kaat deta/deti hoon|I cut my food into small pieces
Mujhe pata rehta hai ki khaane me kitni calories hain|I am aware of the calorie content of foods I eat
Main roti, chawal, aloo jaisi cheezon se khaas taur par bachta/bachti hoon|I particularly avoid foods high in carbohydrates
Mujhe lagta hai doosre chahte hain ki main zyada khaaun|I feel that others would prefer me to eat more
Khaane ke baad main ulti karta/karti hoon|I vomit after I have eaten
Khaane ke baad mujhe bahut guilt hota hai|I feel extremely guilty after eating
Main bahut patla/patli hone ke khayal me lagta/lagti rehta/rehti hoon|I am preoccupied with a desire to be thinner
Exercise karte waqt main sochta/sochti hoon ki kitni calories jal rahi hain|I think about burning calories when I exercise
Doosre mujhe bahut patla/patli samajhte hain|Other people think I am too thin
Mera dhyan sharir par charbi hone ke khayal me rehta hai|I am preoccupied with the thought of having fat on my body
Mujhe doosron se zyada der lagti hai khaana khatam karne me|I take longer than others to finish my meals
Main meethe wale khaane se bachta/bachti hoon|I avoid foods with sugar in them
Main 'diet' wale khaane khaata/khaati hoon|I eat diet foods
Mujhe lagta hai khaana meri zindagi ko control karta hai|I feel that food controls my life
Main khaane ke aas-paas khud par control dikhata/dikhati hoon|I display self-control around food
Mujhe lagta hai log mujhpar khaane ka dabav daalte hain|I feel that others pressure me to eat
Main khaane ke baare me bahut waqt aur soch lagata/lagati hoon|I give too much time and thought to food
Mithai khaane ke baad mujhe asahaj lagta hai|I feel uncomfortable after eating sweets
Main dieting karta/karti hoon|I engage in dieting behaviour
Mujhe pet khaali rehna pasand hai|I like my stomach to be empty
Khaane ke baad mujhe ulti karne ki ichha hoti hai|I have the impulse to vomit after meals
Mujhe naye, bhaari ya swadisht khaane aajmana achha lagta hai|I enjoy trying new rich foods`.split(`
`).map(function(m){return m.split("|")}),calc:function(m){var M=0,f,K;for(f=0;f<26;f++)K=m[f],K!==void 0&&(f==25?M+=K==5?3:K==4?2:K==3?1:0:M+=K==0?3:K==1?2:K==2?1:0);var J=M>=20;return{s:M,b:J?[0,78,"At or above cut-off",j,2]:[0,78,"Below cut-off",e,0],lines:[["Cut-off: 20 ya zyada par khaane ki dikkat ki jaanch layak (0 se 78). Ye diagnosis nahi hai.","Cut-off: 20 or more is worth a fuller assessment (0 to 78). This is not a diagnosis."]],adv:J?["Aapke jawab khaane aur vajan ko lekar kaafi chinta dikhate hain. Ye diagnosis nahi hai. Doctor, psychiatrist ya psychologist se milein; shuru me madad lena sabse acha rehta hai aur ye theek hone wali dikkat hai. "+C[0]+" "+t[0],"Your answers show strong concern about eating and weight. This is not a diagnosis. See a doctor, psychiatrist or psychologist; early help works best and these problems are treatable. "+C[1]+" "+t[1]]:["Cut-off se neeche hai. Khaane ko lekar bada khatra nahi dikha. Chinta badhe to doctor se baat karein.","Below the cut-off. No major eating concern is flagged. If worry grows, talk to a doctor."]}}});function p(m,M,f,K,J,ta,P,U){MC.reg({id:m,name:[M,M],sub:f,max:J.length,opts:a,intro:K,items:J,calc:function(ra){var q=0,Z;for(Z=0;Z<J.length;Z++)q+=ra[Z]||0;var $=q>=ta;return{s:q,b:$?[0,J.length,"Several points apply",j,2]:q>0?[0,J.length,"Few points apply",b,1]:[0,J.length,"No points apply",e,0],lines:[g],adv:$?U:P}}})}p("binge","Binge eating",["Zyada khaane ke daure, 8 sawal","Binge-eating episodes, 8 questions"],["Pichhle 3 mahine ke baare me jawab dein.","Answer about the past 3 months."],[["Kya aap kam samay me itna zyada khaate hain jo aam taur par log nahi khaate?","Do you eat an unusually large amount of food in a short time?"],["Us waqt kya aapko lagta hai ki aap rok nahi sakte ya control kho dete hain?","At those times, do you feel you cannot stop or have lost control?"],["Kya aap normal se bahut tez khaate hain?","Do you eat much faster than normal?"],["Kya aap pet me takleef hone tak khaate hain?","Do you eat until you feel uncomfortably full?"],["Kya aap bhookh na hone par bhi bahut khaate hain?","Do you eat large amounts when you are not hungry?"],["Kya sharm ki wajah se aap akele me chhupkar khaate hain?","Do you eat alone because you are embarrassed?"],["Kya baad me aapko guilt, sharm ya khud se nafrat hoti hai?","Do you feel guilty, ashamed or disgusted with yourself afterwards?"],["Kya aisa hafte me kam se kam ek baar, kai hafton se ho raha hai?","Has this happened at least once a week for several weeks?"]],5,["Abhi zyada khaane ke daure ke lakshan kam dikhte hain. Dheere aur regular khaana, aur bhookh pehchaanna madad karta hai.","Binge-eating signs look limited. Regular, calm meals and noticing hunger cues help."],["Kaafi baatein lagu hui. Ye diagnosis nahi hai aur isme sharm ki baat nahi. Doctor, psychiatrist ya psychologist se milein; CBT aur kuch dawaiyan kaafi madad karti hain. Khud ko sakht diet par rakhne se daure badh sakte hain, isliye diet shuru karne se pehle doctor se baat karein. "+t[0],"Many points apply. This is not a diagnosis and there is nothing to be ashamed of. See a doctor, psychiatrist or psychologist; CBT and some medicines help a lot. Strict dieting can make episodes worse, so talk to a doctor before starting a diet. "+t[1]]);var r=[["Bilkul asehmat","Strongly disagree"],["Asehmat","Disagree"],["Thoda asehmat","Slightly disagree"],["Thoda sehmat","Slightly agree"],["Sehmat","Agree"],["Bilkul sehmat","Strongly agree"]];MC.reg({id:"nias",name:["Avoidant/restrictive eating","Avoidant/restrictive eating"],sub:["Bahut kam ya chuninda khaane ka check, 9 sawal","Check for very limited or selective eating, 9 questions"],max:45,opts:r,intro:["Apni aam khaane ki aadat ke baare me chuniye ki aap kitne sehmat hain. Ye vajan ghatane ki chinta ke bajaye khaane ki chunav, bhookh ya darr ke baare me hai.","Choose how much you agree about your usual eating. This is about food choice, low appetite or fear, not about wanting to lose weight."],items:`Main bahut choosy khaane wala/wali hoon|I am a picky eater
Mujhe bahut kam khaane pasand aate hain|I do not like many foods
Main naye ya anjaane khaane aajmane se bachta/bachti hoon|I avoid trying new or unfamiliar foods
Mujhe zyada bhookh nahi lagti|I do not have much of an appetite
Mujhe khud ko khaane ki yaad dilani padti hai|I have to remind myself to eat
Mujhe jaldi pet bhara ya poora lagta hai|I feel full very quickly
Mujhe khaane se dam ghutne ka darr lagta hai|I am afraid of choking on food
Mujhe darr hai ki khaane se ulti ya bimari hogi, isliye main kam khaata/khaati hoon|I eat less because I fear being sick or vomiting
Mujhe darr hai ki kuch khaane se mujhe kuch bura hoga|I am afraid something bad will happen after eating certain foods`.split(`
`).map(function(m){return m.split("|")}),calc:function(m){var M=o(m,0,2),f=o(m,3,5),K=o(m,6,8),J=[],ta=[],P=[];M>=10&&(ta.push("chuninda khaana"),P.push("picky eating")),f>=8&&(ta.push("kam bhookh"),P.push("low appetite")),K>=10&&(ta.push("darr"),P.push("fear of eating"));var U=o(m,0,8),ra=ta.length?[0,45,"At or above cut-off",j,2]:[0,45,"Below cut-off",e,0];return{s:U,b:ra,lines:[["Teen hisse (0 se 15 har ek): chuninda khaana "+M+" (cut-off 10), kam bhookh "+f+" (cut-off 8), darr "+K+" (cut-off 10). "+(ta.length?"Upar: "+ta.join(", ")+".":"Koi hissa cut-off par nahi."),"Three parts (0 to 15 each): picky eating "+M+" (cut-off 10), low appetite "+f+" (cut-off 8), fear "+K+" (cut-off 10). "+(P.length?"Above: "+P.join(", ")+".":"No part reaches the cut-off.")],["Hamare sawal apne shabdon me hain, isliye cut-off roughly samjhein.","Our questions are worded in our own words, so treat the cut-offs as approximate."]],adv:ta.length?["Aapka khaana kaafi seemit lagta hai. Ye diagnosis nahi hai. Doctor ya psychiatrist se milein taaki poshan aur sehat ki jaanch ho; ARFID jaisi dikkat me therapy kaam karti hai. Bachche ho to maata-pita ke saath jayein. "+t[0],"Your eating seems quite limited. This is not a diagnosis. See a doctor or psychiatrist to check nutrition and health; therapy works for conditions like ARFID. If this is a child, go with a parent. "+t[1]]:["Cut-off se neeche hai. Khaane ki seemit dikkat nahi dikhi.","Below the cut-offs. No restrictive-eating concern is flagged."]}}});var u=function(m,M,f,K){return[[m[0],m[1]],[M[0],M[1]],[f[0],f[1]],[K[0],K[1]]]};MC.reg({id:"ais",name:["Insomnia (sleep problems)","Insomnia (sleep problems)"],sub:["Neend ki dikkat ka check, 8 sawal","Sleep problem check, 8 questions"],max:24,opts:a,intro:["Pichhle 1 mahine ke baare me, jo dikkat hafte me kam se kam 3 baar hui, uske hisaab se chuniye.","Choose based on any problem that happened at least 3 times a week in the past month."],items:[T("Sone me lagne wala waqt (batti band karne ke baad)","Time to fall asleep after lights out",u(["Koi dikkat nahi","No problem"],["Thoda der se","Slightly delayed"],["Kaafi der se","Markedly delayed"],["Bahut der se ya bilkul nahi soye","Very delayed or did not sleep at all"])),T("Raat me beech me jaag jaana","Waking up during the night",u(["Koi dikkat nahi","No problem"],["Thodi dikkat","Minor problem"],["Kaafi dikkat","Considerable problem"],["Bahut dikkat ya bilkul nahi soye","Serious problem or did not sleep at all"])),T("Subah umeed se jaldi uth jaana","Waking earlier than you wanted",u(["Nahi","Not earlier"],["Thoda jaldi","A little earlier"],["Kaafi jaldi","Markedly earlier"],["Bahut jaldi ya bilkul nahi soye","Much earlier or did not sleep at all"])),T("Kul sone ka samay","Total sleep duration",u(["Kaafi","Sufficient"],["Thoda kam","Slightly insufficient"],["Kaafi kam","Markedly insufficient"],["Bahut kam ya bilkul nahi soye","Very insufficient or did not sleep at all"])),T("Neend ki kul quality","Overall quality of sleep",u(["Achhi","Satisfactory"],["Thodi kharab","Slightly unsatisfactory"],["Kaafi kharab","Markedly unsatisfactory"],["Bahut kharab ya bilkul nahi soye","Very unsatisfactory or did not sleep at all"])),T("Din me mann aur mood kaisa raha (well-being)","Sense of well-being during the day",u(["Normal","Normal"],["Thoda kam","Slightly decreased"],["Kaafi kam","Markedly decreased"],["Bahut kam","Very decreased"])),T("Din me kaam karne ki kshamata (sharirik aur mansik)","Functioning during the day (physical and mental)",u(["Normal","Normal"],["Thodi kam","Slightly decreased"],["Kaafi kam","Markedly decreased"],["Bahut kam","Very decreased"])),T("Din me neend ya sustee","Sleepiness during the day",u(["Nahi","None"],["Halki","Mild"],["Kaafi","Considerable"],["Bahut zyada","Intense"]))],calc:function(m){var M=o(m,0,7),f=M>=6;return{s:M,b:f?[0,24,"Insomnia likely",j,2]:[0,24,"Below cut-off",e,0],lines:[["Cut-off: 6 ya zyada par insomnia ki sambhavna (0 se 24). Ye diagnosis nahi hai.","Cut-off: 6 or more suggests insomnia (0 to 24). This is not a diagnosis."]],adv:f?["Neend ki dikkat ke sanket dikhte hain. Roz ek hi samay par sona-uthna, shaam ke baad chai-coffee kam, aur sone se pehle screen se door rehna madad karta hai. Agar 3 mahine se zyada ho ya din ka kaam bigade to doctor se milein; CBT-I naam ki therapy goliyon se behtar lambe samay tak kaam karti hai.","Signs of a sleep problem show. Keeping fixed sleep and wake times, less tea or coffee late in the day, and screens off before bed help. If it lasts over 3 months or hurts your day, see a doctor; a therapy called CBT-I works better than pills over time."]:["Cut-off se neeche hai. Neend ki bada dikkat nahi dikhi.","Below the cut-off. No major sleep problem is flagged."]}}});var i=[["Koi nahi","None"],["Halka","Mild"],["Madhyam","Moderate"],["Gambhir","Severe"],["Bahut gambhir","Very severe"]];MC.reg({id:"isi",name:["Insomnia severity","Insomnia severity"],sub:["Neend ki dikkat kitni gambhir, 7 sawal","How severe is the sleep problem, 7 questions"],max:28,opts:i,intro:["Pichhle 2 hafton ke baare me jawab dein.","Answer about the past 2 weeks."],items:[T("Sone me dikkat (neend aane me der)","Difficulty falling asleep",i),T("Sone ke baad beech me jaag jaana","Difficulty staying asleep",i),T("Subah bahut jaldi aankh khul jaana","Problems waking up too early",i),T("Aap apni abhi ki neend se kitne santusht hain?","How satisfied are you with your current sleep?",[["Bahut santusht","Very satisfied"],["Santusht","Satisfied"],["Theek-thaak","Neutral"],["Asantusht","Dissatisfied"],["Bahut asantusht","Very dissatisfied"]]),T("Aapki neend ki dikkat doosron ko kitni dikhti hai (zindagi par asar)?","How noticeable to others is your sleep problem in terms of its effect on your life?",[["Bilkul nahi","Not at all"],["Thodi","A little"],["Kuch had tak","Somewhat"],["Kaafi","Much"],["Bahut zyada","Very much"]]),T("Aap apni neend ki dikkat ko lekar kitne chintit hain?","How worried are you about your sleep problem?",[["Bilkul nahi","Not at all"],["Thoda","A little"],["Kuch had tak","Somewhat"],["Kaafi","Much"],["Bahut zyada","Very much"]]),T("Neend ki dikkat aapke din ke kaam me kitni rukawat daalti hai (thakaan, mood, dhyan)?","How much does your sleep problem interfere with daily functioning (fatigue, mood, concentration)?",[["Bilkul nahi","Not at all"],["Thodi","A little"],["Kuch had tak","Somewhat"],["Kaafi","Much"],["Bahut zyada","Very much"]])],calc:function(m){var M=o(m,0,6),f=M<=7?[0,28,"No clinical insomnia",e,0]:M<=14?[0,28,"Subthreshold insomnia",b,1]:M<=21?[0,28,"Moderate insomnia",x,2]:[0,28,"Severe insomnia",h,3];return{s:M,b:f,lines:[["Cut-off (0 se 28): 0-7 koi nahi, 8-14 halki, 15-21 madhyam, 22-28 gambhir. Ye diagnosis nahi hai.","Cut-offs (0 to 28): 0-7 none, 8-14 subthreshold, 15-21 moderate, 22-28 severe. This is not a diagnosis."]],adv:M<=7?["Neend ki koi gambhir dikkat nahi dikhi. Sone-uthne ka samay ek jaisa rakhein.","No significant sleep problem is flagged. Keep sleep and wake times regular."]:M<=14?["Halki neend ki dikkat dikhi. Sone ki achhi aadatein (ek jaisa samay, screen kam, shaam ko chai-coffee kam) madad karti hain. 2 hafte baad ye check dobara karein.","A mild sleep problem shows. Good sleep habits (steady times, less screen time, less tea or coffee late) help. Repeat this check in 2 weeks."]:["Neend ki dikkat madhyam se gambhir hai. Doctor se milein: kaaran dhoondhna (tanav, udaasi, apnea, dawai) zaroori hai. CBT-I therapy lambe samay tak sabse achhi kaam karti hai. Neend ki goliyan khud shuru na karein.","The sleep problem is moderate to severe. See a doctor: finding the cause (stress, low mood, apnea, medicines) matters. CBT-I therapy works best long-term. Do not start sleeping pills on your own."]}}}),MC.reg({id:"stopbang",name:["Sleep apnea risk","Sleep apnea risk"],sub:["Neend me saans rukne (apnea) ka risk, 8 sawal","Sleep apnea risk, 8 questions"],max:8,opts:a,intro:["Ye sone me saans rukne ke risk ka chhota screen hai. Har sawal ka Haan ya Nahi chunein.","This is a short screen for the risk of breathing pauses during sleep. Answer Yes or No."],items:[T("Kya aap zor se kharrate lete hain (baat se zyada awaaz ya dusre kamre me sunai de)?","Do you snore loudly (louder than talking, or heard through a closed door)?"),T("Kya aap din me aksar thake ya ghunghte rehte hain?","Do you often feel tired, fatigued or sleepy during the day?"),T("Kya kisi ne dekha hai ki sote waqt aapki saans ruk jaati hai ya aap hanfte hain?","Has anyone seen you stop breathing or gasp during sleep?"),T("Kya aapko high blood pressure hai ya uska ilaaj chal raha hai?","Do you have, or are you being treated for, high blood pressure?"),T("Kya aapka BMI 35 se zyada hai (bahut zyada vajan)?","Is your BMI above 35 (very high body weight)?"),T("Kya aapki umar 50 se zyada hai?","Are you older than 50?"),T("Kya aapki gardan bahut moti hai (shirt ka collar purush: 43 cm / 17 inch ya zyada, mahila: 41 cm / 16 inch ya zyada)?","Is your neck large (shirt collar 43 cm / 17 in or more for men, 41 cm / 16 in or more for women)?"),T("Kya aap purush hain?","Are you male?")],calc:function(m){var M=o(m,0,7),f=o(m,0,3),K=f>=2&&(m[7]||0||m[4]||0||m[6]||0),J=M>=5||K?[0,8,"High risk",h,3]:M>=3?[0,8,"Intermediate risk",x,2]:[0,8,"Low risk",e,0];return{s:M,b:J,lines:[["Cut-off (0 se 8): 0-2 kam, 3-4 madhyam, 5+ zyada risk. 2 se zyada 'STOP' sawal Haan ho aur saath me purush ya BMI ya moti gardan ho, tab bhi zyada risk.","Cut-offs (0 to 8): 0-2 low, 3-4 intermediate, 5 or more high risk. Two or more of the first four answers Yes plus male sex, high BMI or a large neck is also high risk."]],adv:J[4]==3?["Neend me saans rukne (sleep apnea) ka risk zyada hai. Doctor se milein; neend ki jaanch (sleep study) se pakka hota hai. Ilaaj se thakaan, BP aur dil ka khatra kam hota hai. Thake hue gaadi na chalayein.","Your risk of sleep apnea is high. See a doctor; a sleep study confirms it. Treatment lowers tiredness, blood pressure and heart risk. Do not drive when drowsy."]:J[4]==2?["Madhyam risk hai. Doctor ko kharrate aur din ki thakaan ke baare me bataayein; zaroorat par neend ki jaanch hogi. Pith ke bal na soyein aur sharab sone se pehle na lein.","Intermediate risk. Tell a doctor about snoring and daytime tiredness; a sleep test may be needed. Avoid sleeping on your back and alcohol before bed."]:["Risk kam hai. Kharrate ya thakaan badhe to doctor se baat karein.","Risk is low. If snoring or tiredness grows, talk to a doctor."]}}});var k=["self","18+ saal","Ages 18+","Aap khud apne baare me","You, about yourself"];["nias","ais","isi","stopbang","binge"].forEach(function(m){MC.who[m]=k}),MC.who.scoff=["self","13+ saal","Ages 13+","Teen ya adult khud","Teen or adult, self"],MC.who.eat26=["self","16+ saal","Ages 16+","Aap khud apne baare me","You, about yourself"],MC.icd.scoff=["Eating disorders (screen)","6B8","F50"],MC.icd.eat26=["Eating disorders (screen)","6B8","F50"],MC.icd.binge=["Binge eating disorder","6B82","F50.9"],MC.icd.nias=["Avoidant-restrictive food intake disorder","6B83","F50.8"],MC.icd.ais=["Insomnia disorder","7A0","F51.0 / G47.0"],MC.icd.isi=["Insomnia disorder","7A0","F51.0 / G47.0"],MC.icd.stopbang=["Sleep-related breathing disorder (risk)","7A4","G47.3"];var c=["scoff","eat26","binge","nias","ais","isi","stopbang"];c.forEach(function(m){MC.names[m]=MC.tests[m].name[1]}),MC.tabs.a.push({t:["Khaane ki dikkat","Eating problems"],ids:["scoff","eat26","binge","nias"]},{t:["Neend","Sleep"],ids:["ais","isi","stopbang"]});var n={},y=[];["a","c"].forEach(function(m){MC.tabs[m].forEach(function(M){var f=M.ids.filter(function(K){return n[K]||!MC.tests[K]?!1:(n[K]=1,!0)});f.length&&y.push({t:M.t,ids:f})})}),MC.groups=y})()}catch(a){setTimeout(function(){throw a})}